+      try {
+        await (this.client as RedisClientType).quit();
+      } catch {
+        // best-effort
+      }
+      this.client = null;
+      this.connected = false;
+    }
+  }
+
+  // ── Internal ─────────────────────────────────────────────────────────────
+
+  private async _ensureConnected(): Promise<void> {
+    if (!this.connected && this.client) {
+      await (this.client as RedisClientType).connect();
+      this.connected = true;
+    }
+  }
+}
diff --git a/runtime/orchestrator/src/loop/dispatch-reconciler.ts b/runtime/orchestrator/src/loop/dispatch-reconciler.ts
