+// ── Fake Redis client ─────────────────────────────────────────────────────────
+
+interface FakeStreamEntry {
+  id: string;
+  fields: Record<string, string>;
+}
+
+class FakeRedisClient {
+  readonly streams = new Map<string, FakeStreamEntry[]>();
+  connected = false;
+
+  async connect(): Promise<void> {
+    this.connected = true;
+  }
+
+  async quit(): Promise<void> {
+    this.connected = false;
+  }
+
+  async xAdd(
+    key: string,
+    _id: string,
+    fields: Record<string, string>,
+  ): Promise<string> {
+    const id = `${Date.now()}-0`;
+    const entries = this.streams.get(key) ?? [];
+    entries.push({ id, fields });
+    this.streams.set(key, entries);
+    return id;
+  }
+
+  lastEntry(streamKey: string): FakeStreamEntry | undefined {
+    const entries = this.streams.get(streamKey) ?? [];
+    return entries[entries.length - 1];
+  }
+}
+
+// ── Fake broker ───────────────────────────────────────────────────────────────
+
+interface Registration {
+  handle: string;
+  nonce: string;
+  metadata: Record<string, unknown>;
+}
+
+class FakeBroker {
+  registrations: Registration[] = [];
+  ackedHandles: string[] = [];
+
+  async register(
+    handle: string,
+    nonce: string,
+    metadata: Record<string, unknown>,
+  ): Promise<void> {
+    this.registrations.push({ handle, nonce, metadata });
+  }
+
+  async ack(handle: string): Promise<void> {
+    this.ackedHandles.push(handle);
+  }
+
+  async nack(_handle: string): Promise<void> { /* no-op */ }
+
+  async listCompleted() { return []; }
+  getCallbackUrl(): string { return "http://broker:7000/callback"; }
+  inFlightCount(): number { return 0; }
+  registrySize(): number { return 0; }
+  start(): Promise<number> { return Promise.resolve(7000); }
+  stop(): Promise<void> { return Promise.resolve(); }
+}
