+/**
+ * Unit tests for QueueDispatchAdapter (T5 — standalone-executor-hardening).
+ *
+ * Uses a fake Redis client (in-memory) and a FakeBrokerAdapter to verify:
+ *   1. submit() registers handle+nonce with the broker before XADDing.
+ *   2. submit() XADDs a credential-free DispatchJob to the dispatch stream.
+ *   3. DispatchJob fields are mapped correctly from ExecutorPortInput.
+ *   4. No secrets (sshPrivateKey, githubToken) appear in the stream entry.
+ *   5. ack() delegates to broker.ack().
+ *   6. readResult() returns a tombstone (results arrive via broker callback).
+ *   7. submit() resolves to the handle immediately (non-blocking).
+ */
+
+import { describe, it, expect, vi, beforeEach } from "vitest";
+import { QueueDispatchAdapter } from "../src/executor/queue-dispatch.js";
+import { DISPATCH_STREAM_KEY } from "@workflow/runtime-abi";
+import type { ExecutorPortInput } from "@workflow/runtime-abi";
+
+// ── Fake Redis client ─────────────────────────────────────────────────────────
+
+interface FakeStreamEntry {
+  id: string;
+  fields: Record<string, string>;
+}
+
+class FakeRedisClient {
+  readonly streams = new Map<string, FakeStreamEntry[]>();
+  connected = false;
+
+  async connect(): Promise<void> {
+    this.connected = true;
+  }
+
+  async quit(): Promise<void> {
+    this.connected = false;
+  }
+
+  async xAdd(
+    key: string,
+    _id: string,
+    fields: Record<string, string>,
+  ): Promise<string> {
+    const id = `${Date.now()}-0`;
+    const entries = this.streams.get(key) ?? [];
+    entries.push({ id, fields });
+    this.streams.set(key, entries);
+    return id;
+  }
+
+  lastEntry(streamKey: string): FakeStreamEntry | undefined {
+    const entries = this.streams.get(streamKey) ?? [];
+    return entries[entries.length - 1];
+  }
+}
+
+// ── Fake broker ───────────────────────────────────────────────────────────────
+
+interface Registration {
+  handle: string;
+  nonce: string;
+  metadata: Record<string, unknown>;
+}
+
+class FakeBroker {
+  registrations: Registration[] = [];
+  ackedHandles: string[] = [];
+
+  async register(
+    handle: string,
+    nonce: string,
+    metadata: Record<string, unknown>,
+  ): Promise<void> {
+    this.registrations.push({ handle, nonce, metadata });
+  }
+
+  async ack(handle: string): Promise<void> {
+    this.ackedHandles.push(handle);
+  }
+
+  async nack(_handle: string): Promise<void> { /* no-op */ }
+
+  async listCompleted() { return []; }
+  getCallbackUrl(): string { return "http://broker:7000/callback"; }
+  inFlightCount(): number { return 0; }
+  registrySize(): number { return 0; }
+  start(): Promise<number> { return Promise.resolve(7000); }
+  stop(): Promise<void> { return Promise.resolve(); }
+}
+
+// ── Helpers ───────────────────────────────────────────────────────────────────
+
+function makeInput(overrides: Partial<ExecutorPortInput> = {}): ExecutorPortInput {
+  return {
+    taskId: "T5",
+    featureId: "standalone-executor-hardening",
+    workspaceId: "ws-test",
+    handle: "handle-uuid-1234",
+    taskRepoUrl: "git@github.com:org/impl.git",
+    taskRepoBranch: "feature/standalone-executor-hardening-T5",
+    taskBaseBranch: "feature/standalone-executor-hardening",
+    taskRepoBaseBranch: "main",
+    executorWorkdir: "/workspaces/exec-handle-uuid-1234",
+    mgmtRepoUrl: "git@github.com:org/mgmt.git",
+    resultPath: "/tmp/executor-result-T5.json",
+    callbackUrl: "http://broker:7000/callback",
+    nonce: "nonce-uuid-5678",
+    sshPrivateKey: "SSH_PRIVATE_KEY_SECRET",
+    githubToken: "GITHUB_TOKEN_SECRET",
+    budgetTokens: 500_000,
+    implementationModel: "claude-sonnet-4-6",
+    ...overrides,
+  };
+}
+
+function makeAdapter(
+  broker: FakeBroker,
+  redisClient: FakeRedisClient,
+): QueueDispatchAdapter {
+  return new QueueDispatchAdapter({
+    broker: broker as never,
+    redisClient: redisClient as never,
+    workspacesDir: "/workspaces",
+  });
+}
+
+// ── Tests ─────────────────────────────────────────────────────────────────────
+
+describe("QueueDispatchAdapter", () => {
+  let broker: FakeBroker;
+  let redis: FakeRedisClient;
