+
+    expect(broker.registrations).toHaveLength(1);
+    expect(broker.registrations[0]!.handle).toBe(input.handle);
+    expect(broker.registrations[0]!.nonce).toBe(input.nonce);
+    expect(broker.registrations[0]!.metadata.task_id).toBe(input.taskId);
+    expect(broker.registrations[0]!.metadata.feature_id).toBe(input.featureId);
+  });
+
+  it("registers broker before the stream XADD (ordering via call sequence)", async () => {
+    const callOrder: string[] = [];
+    const origRegister = broker.register.bind(broker);
+    const origXAdd = redis.xAdd.bind(redis);
+    broker.register = async (...args) => { callOrder.push("register"); return origRegister(...args); };
+    redis.xAdd = async (...args) => { callOrder.push("xAdd"); return origXAdd(...args); };
+
+    await adapter.submit(makeInput());
+
+    expect(callOrder).toEqual(["register", "xAdd"]);
+  });
+
+  // ── 2. Dispatch stream XADD ──────────────────────────────────────────────

